"""Independent naive reference implementation (spec-literal) for cross-checks."""
import json
from collections import deque

CAP = 20000


def monitor(op, p):
    """Return (m, delta) where delta(state, token) -> state; truth state is m."""
    m = len(p)
    if op == 'match':
        fail = m + 1

        def delta(k, a):
            if k < m and a == p[k]:
                return k + 1
            if k == m:
                return fail
            return fail
        return m, delta
    if op == 'startswith':
        fail = m + 1

        def delta(k, a):
            if k < m and a == p[k]:
                return k + 1
            if k == m:
                return m
            return fail
        return m, delta
    if op == 'endswith':
        def delta(k, a):
            cur = p[:k] + [a]
            best = 0
            top = min(k + 1, m)
            for j in range(top + 1):
                if p[:j] == cur[len(cur) - j:]:
                    best = j
            return best
        return m, delta
    if op == 'contains':
        def delta(k, a):
            if k == m:
                return m
            cur = p[:k] + [a]
            best = 0
            top = min(k + 1, m)
            for j in range(top + 1):
                if p[:j] == cur[len(cur) - j:]:
                    best = j
            return best
        return m, delta
    raise AssertionError(op)


def atoms_of(rules):
    seen = []
    keys = set()
    for _act, when in rules:
        collect(when, seen, keys)
    return seen


def collect(node, seen, keys):
    op = node['op']
    if op in ('true', 'false'):
        return
    if op in ('match', 'startswith', 'endswith', 'contains'):
        key = (op, tuple(node['path']))
        if key not in keys:
            keys.add(key)
            seen.append(key)
        return
    if op == 'not':
        collect(node['arg'], seen, keys)
        return
    for child in node['args']:
        collect(child, seen, keys)


def evaluate(node, truth):
    op = node['op']
    if op == 'true':
        return True
    if op == 'false':
        return False
    if op in ('match', 'startswith', 'endswith', 'contains'):
        return truth[(op, tuple(node['path']))]
    if op == 'not':
        return not evaluate(node['arg'], truth)
    if op == 'and':
        return all(evaluate(c, truth) for c in node['args'])
    if op == 'or':
        return any(evaluate(c, truth) for c in node['args'])
    raise AssertionError(op)


def product_states(atoms, services):
    """Naive product exploration.  Returns (order, per-state truth dict) or None if over cap."""
    mons = []
    for op, p in atoms:
        m, delta = monitor(op, list(p))
        mons.append((op, list(p), m, delta))
    init = (0,) * len(mons)
    seen = {init: 0}
    order = [init]
    i = 0
    while i < len(order):
        cur = order[i]
        i += 1
        for tok in services:
            nxt = tuple(mons[j][3](cur[j], tok) for j in range(len(mons)))
            if nxt not in seen:
                if len(order) >= CAP:
                    return None
                seen[nxt] = len(order)
                order.append(nxt)
    return order, mons


